(R/'notes/world_v016/combined_export_reopen_v043.json').write_text(json.dumps({'source':str(source),'sha256':build['source_sha256'],'cold_native_reopen':True,'master_scene':s.name,'world_scene':w.name,'frames':[1801,1920],'frame_count':120,'fps':24,'output_resolution':[3840,2160],'live_native_scene_strip':True,'original_audio_native_trim':[75,80],'picture_cache_dependency':False,'output':str(out),'render_status':'Launching bounded120frame nativeexport; completion not yet claimed.'},indent=2))
